                {showParticipantModal && (
                    <div className="fixed inset-0 bg-black bg-opacity-60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                        <div className="bg-white rounded-2xl shadow-2xl max-w-3xl w-full transform transition-all duration-300 scale-100">
                            {/* Modal Header */}
                            <div className="relative bg-gradient-to-r from-emerald-600 to-teal-600 px-8 py-6 rounded-t-2xl">
                                <div className="absolute top-0 right-0 w-32 h-32 bg-white opacity-5 rounded-full -mr-16 -mt-16"></div>
                                <div className="absolute bottom-0 left-0 w-24 h-24 bg-white opacity-5 rounded-full -ml-12 -mb-12"></div>
                                <h2 className="relative text-2xl font-bold text-white">Gérer les Participants</h2>
                                <p className="relative text-emerald-100 text-sm mt-1">
                                    Formation: {selectedTraining?.title}
                                </p>
                            </div>

                            {/* Modal Body */}
                            <div className="p-8">
                                <form onSubmit={handleParticipantSubmit} className="space-y-6">
                                    <div>
                                        <label className="block text-sm font-semibold text-slate-700 mb-4 flex items-center">
                                            <svg className="w-5 h-5 mr-2 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" />
                                            </svg>
                                            Sélectionner les participants
                                        </label>
                                        <div className="max-h-80 overflow-y-auto border border-slate-200 rounded-xl p-4 space-y-2">
                                            {participants.map(participant => (
                                                <div key={participant.id} className="group flex items-center p-3 rounded-lg hover:bg-slate-50 transition-colors duration-200">
                                                    <input
                                                        type="checkbox"
                                                        id={`participant-${participant.id}`}
                                                        value={participant.id}
                                                        checked={selectedParticipants.includes(participant.id)}
                                                        onChange={() => handleParticipantChange(participant.id)}
                                                        className="w-5 h-5 text-emerald-600 border-slate-300 rounded focus:ring-emerald-500 focus:ring-2"
                                                    />
                                                    <label 
                                                        htmlFor={`participant-${participant.id}`}
                                                        className="ml-4 flex-1 cursor-pointer flex items-center justify-between"
                                                    >
                                                        <div className="flex items-center">
                                                            <div className="w-10 h-10 bg-gradient-to-br from-slate-200 to-slate-300 rounded-full flex items-center justify-center mr-3">
                                                                <span className="text-slate-600 font-semibold text-sm">
                                                                    {participant.fullName.split(' ').map(n => n[0]).join('').toUpperCase()}
                                                                </span>
                                                            </div>
                                                            <div>
                                                                <p className="text-sm font-medium text-slate-800">{participant.fullName}</p>
                                                                <p className="text-xs text-slate-500">Participant</p>
                                                            </div>
                                                        </div>
                                                        {selectedParticipants.includes(participant.id) && (
                                                            <div className="bg-emerald-100 text-emerald-700 text-xs font-semibold px-2 py-1 rounded-full">
                                                                Sélectionné
                                                            </div>
                                                        )}
                                                    </label>
                                                </div>
                                            ))}
                                            {participants.length === 0 && (
                                                <div className="text-center py-12">
                                                    <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4">
                                                        <svg className="w-8 h-8 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" />
                                                        </svg>
                                                    </div>
                                                    <p className="text-slate-600 font-medium">Aucun participant disponible</p>
                                                    <p className="text-slate-400 text-sm mt-1">Ajoutez d'abord des participants au système</p>
                                                </div>
                                            )}
                                        </div>
                                        {selectedParticipants.length > 0 && (
                                            <div className="mt-4 bg-emerald-50 border border-emerald-200 rounded-xl p-4">
                                                <div className="flex items-center">
                                                    <svg className="w-5 h-5 text-emerald-600 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                                                    </svg>
                                                    <p className="text-emerald-800 font-medium">
                                                        {selectedParticipants.length} participant{selectedParticipants.length > 1 ? 's' : ''} sélectionné{selectedParticipants.length > 1 ? 's' : ''}
                                                    </p>
                                                </div>
                                            </div>
                                        )}
                                    </div>

                                    <div className="flex space-x-3 pt-6">
                                        <button
                                            type="submit"
                                            disabled={selectedParticipants.length === 0}
                                            className="flex-1 bg-gradient-to-r from-emerald-600 to-teal-600 text-white py-3 rounded-xl font-semibold hover:shadow-lg transform hover:-translate-y-0.5 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed disabled:transform-none flex items-center justify-center"
                                        >
                                            <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                                            </svg>
                                            Ajouter ({selectedParticipants.length})
                                        </button>
                                        <button
                                            type="button"
                                            onClick={() => {
                                                setShowParticipantModal(false);
                                                setSelectedTraining(null);
                                                setSelectedParticipants([]);
                                            }}
                                            className="flex-1 bg-slate-100 text-slate-700 py-3 rounded-xl font-semibold hover:bg-slate-200 transition-colors duration-200"
                                        >
                                            Annuler
                                        </button>
                                    </div>
                                </form>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Formation;
